import { randomUUID } from "node:crypto";
import { join } from "node:path";
import {
  ControlDecisionPacketSchema,
  ControlDecisionSchema,
  contentHash,
  type CanonicalHashAlgorithm,
  type ControlDecision,
  type ControlDecisionPacket,
  type Graph,
  type RunEvent,
  type RunState,
} from "@graphcraft/core";
import { RunLock } from "./lock.ts";
import { redactValue } from "./redaction.ts";
import type { RunStore } from "./store.ts";

export interface UserControlDecisionInput {
  sourceId: string;
  targetId: string;
  verdict: "approve" | "veto";
  rationale: string;
  evidence?: string[];
  replaces?: string;
}

export interface ControlEvaluation {
  allowed: boolean;
  reason?: string;
  packet?: ControlDecisionPacket;
}

function decisionFor(
  state: RunState,
  sourceId: string,
  targetId: string,
  algorithm: CanonicalHashAlgorithm,
): ControlDecision | undefined {
  const explicit = state.controlDecisions.findLast(
    (decision) => decision.sourceId === sourceId && decision.targetId === targetId,
  );
  if (explicit) return explicit;
  const sourceState = state.nodes[sourceId];
  if (!sourceState || !["accepted", "failed", "blocked", "stopped"].includes(sourceState.status))
    return undefined;
  const identity = {
    schemaVersion: 1,
    kind: "node_control_decision",
    sourceId,
    targetId,
    state: {
      status: sourceState.status,
      attempts: sourceState.attempts,
      lastSummary: sourceState.lastSummary ?? null,
      lastProgress: sourceState.lastProgress ?? null,
      acceptedAt: sourceState.acceptedAt ?? null,
    },
  };
  const hash = contentHash(identity, algorithm);
  return ControlDecisionSchema.parse({
    schemaVersion: 1,
    decisionId: `${hash.slice(0, 8)}-${hash.slice(8, 12)}-5${hash.slice(13, 16)}-8${hash.slice(17, 20)}-${hash.slice(20, 32)}`,
    sourceId,
    targetId,
    verdict: sourceState.status === "accepted" ? "approve" : "veto",
    rationale: `Control source node ${sourceId} is ${sourceState.status}`,
    evidence: sourceState.lastSummary ? [sourceState.lastSummary] : [],
    actor: "runtime",
    sticky: false,
    decidedAt: state.updatedAt,
  });
}

function controlSourceGenerationIdentity(
  state: RunState,
  sourceId: string,
  targetId: string,
  algorithm: CanonicalHashAlgorithm,
): Record<string, unknown> {
  const explicit = state.controlDecisions.findLast(
    (decision) => decision.sourceId === sourceId && decision.targetId === targetId,
  );
  if (explicit)
    return {
      sourceId,
      targetId,
      kind: "explicit",
      decisionId: explicit.decisionId,
    };
  const sourceState = state.nodes[sourceId];
  const projected = decisionFor(state, sourceId, targetId, algorithm);
  return projected
    ? {
        sourceId,
        targetId,
        kind: "node",
        decisionId: projected.decisionId,
      }
    : {
        sourceId,
        targetId,
        kind: "unresolved",
        state: sourceState
          ? {
              status: sourceState.status,
              attempts: sourceState.attempts,
              lastSummary: sourceState.lastSummary ?? null,
              lastProgress: sourceState.lastProgress ?? null,
              acceptedAt: sourceState.acceptedAt ?? null,
            }
          : null,
      };
}

type CheckpointedControlEventType =
  | "control.decision"
  | "control.observed"
  | "control.override"
  | "control.decision_required"
  | "control.resolved";

async function appendCheckpointedControlEvent(input: {
  store: RunStore;
  actor: RunEvent["actor"];
  type: CheckpointedControlEventType;
  data: Record<string, unknown>;
  checkpointId?: string;
  controlGenerationId?: string;
  identity?: unknown;
  causationId?: string;
}): Promise<RunEvent> {
  if (!input.checkpointId)
    return await input.store.append(input.actor, input.type, input.data, input.causationId);
  const operationId = contentHash(
    {
      schemaVersion: 1,
      kind: input.type,
      checkpointId: input.checkpointId,
      controlGenerationId: input.controlGenerationId ?? null,
      identity: redactValue(input.identity ?? input.data),
    },
    input.store.governanceControlIdentityHashAlgorithm,
  );
  const existing = (await input.store.loadEvents()).find(
    ({ type, data }) => type === input.type && data.operationId === operationId,
  );
  if (existing) return existing;
  return await input.store.append(
    input.actor,
    input.type,
    {
      ...input.data,
      checkpointId: input.checkpointId,
      ...(input.controlGenerationId ? { controlGenerationId: input.controlGenerationId } : {}),
      operationId,
    },
    operationId,
  );
}

async function appendDecision(
  store: RunStore,
  decision: ControlDecision,
  checkpointId?: string,
): Promise<ControlDecision> {
  if (!checkpointId) {
    await appendCheckpointedControlEvent({
      store,
      actor:
        decision.actor === "user" ? "user" : decision.actor === "verifier" ? "host" : "runtime",
      type: "control.decision",
      data: { decision },
      causationId: decision.decisionId,
    });
    return decision;
  }
  const durableDecision = ControlDecisionSchema.parse(redactValue(decision));
  const [state, events] = await Promise.all([store.loadState(), store.loadEvents()]);
  const current = state.controlDecisions.findLast(
    ({ sourceId, targetId }) =>
      sourceId === durableDecision.sourceId && targetId === durableDecision.targetId,
  );
  const currentMatches =
    current?.verdict === durableDecision.verdict &&
    current.rationale === durableDecision.rationale &&
    JSON.stringify(current.evidence) === JSON.stringify(durableDecision.evidence) &&
    current.actor === durableDecision.actor &&
    current.sticky === durableDecision.sticky &&
    current.replaces === durableDecision.replaces;
  const currentBelongsToCheckpoint =
    currentMatches &&
    events.some(({ type, data }) => {
      if (type !== "control.decision" || data.checkpointId !== checkpointId) return false;
      const persisted = ControlDecisionSchema.safeParse(data.decision);
      return persisted.success && persisted.data.decisionId === current?.decisionId;
    });
  if (currentMatches && currentBelongsToCheckpoint) return current;
  const event = await appendCheckpointedControlEvent({
    store,
    actor:
      durableDecision.actor === "user"
        ? "user"
        : durableDecision.actor === "verifier"
          ? "host"
          : "runtime",
    type: "control.decision",
    data: { decision: durableDecision },
    checkpointId,
    causationId: durableDecision.decisionId,
    identity: {
      sourceId: durableDecision.sourceId,
      targetId: durableDecision.targetId,
      verdict: durableDecision.verdict,
      rationale: durableDecision.rationale,
      evidence: durableDecision.evidence,
      actor: durableDecision.actor,
      sticky: durableDecision.sticky,
      predecessorDecisionId: current?.decisionId ?? null,
    },
  });
  return ControlDecisionSchema.parse(event.data.decision);
}

function authorityEdge(graph: Graph, sourceId: string, targetId: string): boolean {
  return graph.controlEdges.some(
    (edge) =>
      edge.from === sourceId &&
      edge.to === targetId &&
      ["vetoes", "arbitrates", "owns_target"].includes(edge.relation),
  );
}

export async function recordRuntimeControlDecision(input: {
  store: RunStore;
  graph: Graph;
  sourceId: string;
  targetId: string;
  verdict: "approve" | "veto";
  rationale: string;
  evidence: string[];
  actor: "runtime" | "verifier";
  checkpointId?: string;
}): Promise<ControlDecision> {
  if (!authorityEdge(input.graph, input.sourceId, input.targetId))
    throw new Error(`Control source ${input.sourceId} has no authority over ${input.targetId}`);
  const anchor = input.graph.anchors.find(({ id }) => id === input.sourceId);
  if (anchor?.owner === "user")
    throw new Error(`Runtime actors cannot impersonate user-owned source ${input.sourceId}`);
  if (input.actor === "verifier" && anchor?.owner !== "held_out_eval")
    throw new Error(`Verifier source ${input.sourceId} is not owned by a held-out evaluator`);
  const decision = ControlDecisionSchema.parse({
    schemaVersion: 1,
    decisionId: randomUUID(),
    sourceId: input.sourceId,
    targetId: input.targetId,
    verdict: input.verdict,
    rationale: input.rationale,
    evidence: input.evidence,
    actor: input.actor,
    sticky: false,
    decidedAt: new Date().toISOString(),
  });
  return await appendDecision(input.store, decision, input.checkpointId);
}

export async function recordRunApprovalDecisions(store: RunStore, graph: Graph): Promise<void> {
  const state = await store.loadState();
  const anchors = new Map(graph.anchors.map((anchor) => [anchor.id, anchor]));
  for (const edge of graph.controlEdges.filter(({ relation }) => relation === "owns_target")) {
    if (
      anchors.get(edge.from)?.owner !== "user" ||
      decisionFor(state, edge.from, edge.to, store.governanceControlIdentityHashAlgorithm)
    )
      continue;
    await appendDecision(
      store,
      ControlDecisionSchema.parse({
        schemaVersion: 1,
        decisionId: randomUUID(),
        sourceId: edge.from,
        targetId: edge.to,
        verdict: "approve",
        rationale: "The user approved the displayed run contract, graph, and finish line",
        evidence: ["run.approved"],
        actor: "user",
        sticky: true,
        decidedAt: new Date().toISOString(),
      }),
    );
  }
}

function packet(input: {
  targetId: string;
  conflict: string;
  evidence: string[];
  requiredSources: string[];
}): ControlDecisionPacket {
  return ControlDecisionPacketSchema.parse({
    packetId: randomUUID(),
    targetId: input.targetId,
    invariant: "A controlled node cannot run or be accepted without resolved authority",
    conflict: input.conflict,
    evidence: input.evidence,
    requiredSources: [...new Set(input.requiredSources)],
    choices: ["approve", "veto"],
    createdAt: new Date().toISOString(),
  });
}

async function requireDecision(
  store: RunStore,
  targetId: string,
  conflict: string,
  evidence: string[],
  requiredSources: string[],
  checkpointId?: string,
  controlGenerationId?: string,
): Promise<ControlEvaluation> {
  const required = [...new Set(requiredSources)];
  const existing = (await store.loadState()).pendingDecision;
  if (
    existing?.targetId === targetId &&
    existing.conflict === conflict &&
    JSON.stringify([...existing.requiredSources].sort()) === JSON.stringify([...required].sort())
  ) {
    if (!checkpointId) return { allowed: false, reason: conflict, packet: existing };
    const existingEvent = (await store.loadEvents()).findLast(
      ({ type, data }) =>
        type === "control.decision_required" &&
        typeof data.packet === "object" &&
        data.packet !== null &&
        (data.packet as { packetId?: unknown }).packetId === existing.packetId,
    );
    if (
      existingEvent?.data.checkpointId === checkpointId &&
      existingEvent.data.controlGenerationId === controlGenerationId
    )
      return { allowed: false, reason: conflict, packet: existing };
  }
  const value = packet({ targetId, conflict, evidence, requiredSources });
  const event = await appendCheckpointedControlEvent({
    store,
    actor: "runtime",
    type: "control.decision_required",
    data: { packet: value },
    ...(checkpointId ? { checkpointId } : {}),
    ...(controlGenerationId ? { controlGenerationId } : {}),
    causationId: value.packetId,
    identity: { targetId, conflict, evidence, requiredSources: required },
  });
  return {
    allowed: false,
    reason: conflict,
    packet: ControlDecisionPacketSchema.parse(event.data.packet),
  };
}

function decisionsFor(
  state: RunState,
  edges: Graph["controlEdges"],
  targetId: string,
  algorithm: CanonicalHashAlgorithm,
): ControlDecision[] {
  return edges
    .map((edge) => decisionFor(state, edge.from, targetId, algorithm))
    .filter((decision): decision is ControlDecision => decision !== undefined);
}

function unanimousDecision(decisions: ControlDecision[]): ControlDecision | "conflict" | undefined {
  if (decisions.length === 0) return undefined;
  if (new Set(decisions.map(({ verdict }) => verdict)).size > 1) return "conflict";
  return decisions[0];
}

async function recordOverride(
  store: RunStore,
  targetId: string,
  arbitrator: ControlDecision,
  overridden: ControlDecision[],
  missingSources: string[] = [],
  checkpointId?: string,
  controlGenerationId?: string,
): Promise<void> {
  const data = {
    targetId,
    arbitrator: arbitrator.sourceId,
    arbitratorDecisionId: arbitrator.decisionId,
    rationale: arbitrator.rationale,
    overridden: overridden.map(({ sourceId }) => sourceId),
    overriddenDecisionIds: overridden.map(({ decisionId }) => decisionId),
    missingSources,
    evidence: arbitrator.evidence,
  };
  await appendCheckpointedControlEvent({
    store,
    actor: arbitrator.actor === "user" ? "user" : "runtime",
    type: "control.override",
    data,
    ...(checkpointId ? { checkpointId } : {}),
    ...(controlGenerationId ? { controlGenerationId } : {}),
  });
}

async function recordResolution(
  store: RunStore,
  targetId: string,
  outcome: "approved" | "vetoed",
  owners: ControlDecision[],
  evidence: string[],
  checkpointId?: string,
  controlGenerationId?: string,
): Promise<void> {
  await appendCheckpointedControlEvent({
    store,
    actor: "runtime",
    type: "control.resolved",
    data: {
      targetId,
      outcome,
      owners: owners.map(({ sourceId }) => sourceId),
      ownerDecisionIds: owners.map(({ decisionId }) => decisionId),
      evidence,
    },
    ...(checkpointId ? { checkpointId } : {}),
    ...(controlGenerationId ? { controlGenerationId } : {}),
  });
}

export async function evaluateControlScheduling(
  store: RunStore,
  graph: Graph,
  state: RunState,
  targetId: string,
  checkpointId?: string,
): Promise<ControlEvaluation> {
  const incoming = graph.controlEdges.filter((edge) => edge.to === targetId);
  const owners = graph.controlEdges.filter(
    (edge) => edge.to === targetId && edge.relation === "owns_target",
  );
  if (owners.length === 0) return { allowed: true };
  const controlGenerationId = checkpointId
    ? contentHash(
        {
          schemaVersion: 1,
          kind: "control_scheduling_generation",
          checkpointId,
          targetId,
          sources: [...new Set(incoming.map(({ from }) => from))]
            .sort()
            .map((sourceId) =>
              controlSourceGenerationIdentity(
                state,
                sourceId,
                targetId,
                store.governanceControlIdentityHashAlgorithm,
              ),
            ),
        },
        store.governanceControlIdentityHashAlgorithm,
      )
    : undefined;
  const ownerDecisions = decisionsFor(
    state,
    owners,
    targetId,
    store.governanceControlIdentityHashAlgorithm,
  );
  const ownerApprovals = ownerDecisions.filter(({ verdict }) => verdict === "approve");
  const ownerVetoes = ownerDecisions.filter(({ verdict }) => verdict === "veto");
  const missing = owners.filter(
    (edge) => !ownerDecisions.some(({ sourceId }) => sourceId === edge.from),
  );
  const arbitratorEdges = graph.controlEdges.filter(
    (edge) => edge.to === targetId && edge.relation === "arbitrates",
  );
  const arbitrators = decisionsFor(
    state,
    arbitratorEdges,
    targetId,
    store.governanceControlIdentityHashAlgorithm,
  );
  const arbitrator = unanimousDecision(arbitrators);

  if (arbitrator === "conflict") {
    return await requireDecision(
      store,
      targetId,
      `Arbitrators disagree about scheduling ${targetId}`,
      arbitrators.flatMap(({ evidence }) => evidence),
      arbitratorEdges.map(({ from }) => from),
      checkpointId,
      controlGenerationId,
    );
  }

  if (missing.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        missing.map(({ from }) => from),
        checkpointId,
        controlGenerationId,
      );
      await recordResolution(
        store,
        targetId,
        "approved",
        ownerApprovals,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: true };
    }
    if (arbitrator?.verdict === "veto") {
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerDecisions,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return {
        allowed: false,
        reason: `Arbitrator vetoed scheduling ${targetId}: ${arbitrator.sourceId}`,
      };
    }
    return await requireDecision(
      store,
      targetId,
      `Control owners have not authorized ${targetId}`,
      ownerDecisions.flatMap(({ evidence }) => evidence),
      arbitratorEdges.length > 0
        ? arbitratorEdges.map(({ from }) => from)
        : missing.map(({ from }) => from),
      checkpointId,
      controlGenerationId,
    );
  }

  if (ownerApprovals.length > 0 && ownerVetoes.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        [],
        checkpointId,
        controlGenerationId,
      );
      await recordResolution(
        store,
        targetId,
        "approved",
        ownerApprovals,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: true };
    }
    if (arbitrator?.verdict === "veto") {
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerDecisions,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return {
        allowed: false,
        reason: `Arbitrator vetoed scheduling ${targetId}: ${arbitrator.sourceId}`,
      };
    }
    return await requireDecision(
      store,
      targetId,
      `Control owners disagree about scheduling ${targetId}`,
      ownerDecisions.flatMap(({ evidence }) => evidence),
      arbitratorEdges.length > 0
        ? arbitratorEdges.map(({ from }) => from)
        : owners.map(({ from }) => from),
      checkpointId,
      controlGenerationId,
    );
  }

  if (ownerVetoes.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        [],
        checkpointId,
        controlGenerationId,
      );
      await recordResolution(
        store,
        targetId,
        "approved",
        [],
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: true };
    }
    const reason = `Control owner vetoed ${targetId}: ${ownerVetoes
      .map(({ sourceId }) => sourceId)
      .join(", ")}`;
    await recordResolution(
      store,
      targetId,
      "vetoed",
      ownerVetoes,
      ownerVetoes.flatMap(({ evidence }) => evidence),
      checkpointId,
      controlGenerationId,
    );
    return { allowed: false, reason };
  }
  return { allowed: true };
}

export async function evaluateControlAcceptance(
  store: RunStore,
  graph: Graph,
  state: RunState,
  targetId: string,
  evidence: string[],
  checkpointId?: string,
): Promise<ControlEvaluation> {
  const incoming = graph.controlEdges.filter((edge) => edge.to === targetId);
  const controlGenerationId = checkpointId
    ? contentHash(
        {
          schemaVersion: 1,
          kind: "control_acceptance_generation",
          checkpointId,
          targetId,
          sources: [...new Set(incoming.map(({ from }) => from))]
            .sort()
            .map((sourceId) =>
              controlSourceGenerationIdentity(
                state,
                sourceId,
                targetId,
                store.governanceControlIdentityHashAlgorithm,
              ),
            ),
        },
        store.governanceControlIdentityHashAlgorithm,
      )
    : undefined;
  for (const edge of incoming.filter(({ relation }) => relation === "observes")) {
    await appendCheckpointedControlEvent({
      store,
      actor: "runtime",
      type: "control.observed",
      data: { observer: edge.from, targetId, evidence },
      ...(checkpointId ? { checkpointId } : {}),
      ...(controlGenerationId ? { controlGenerationId } : {}),
    });
  }

  const owners = incoming.filter(({ relation }) => relation === "owns_target");
  const ownerDecisions = decisionsFor(
    state,
    owners,
    targetId,
    store.governanceControlIdentityHashAlgorithm,
  );
  const missingOwners = owners.filter(
    (edge) => !ownerDecisions.some(({ sourceId }) => sourceId === edge.from),
  );
  let ownerApprovals = ownerDecisions.filter(({ verdict }) => verdict === "approve");
  let ownerVetoes = ownerDecisions.filter(({ verdict }) => verdict === "veto");
  const arbitratorEdges = incoming.filter(({ relation }) => relation === "arbitrates");
  const arbitrators = decisionsFor(
    state,
    arbitratorEdges,
    targetId,
    store.governanceControlIdentityHashAlgorithm,
  );
  const arbitrator = unanimousDecision(arbitrators);

  if (arbitrator === "conflict") {
    return await requireDecision(
      store,
      targetId,
      `Arbitrators disagree about ${targetId}`,
      [...evidence, ...arbitrators.flatMap(({ evidence: value }) => value)],
      arbitratorEdges.map(({ from }) => from),
      checkpointId,
      controlGenerationId,
    );
  }

  if (missingOwners.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        missingOwners.map(({ from }) => from),
        checkpointId,
        controlGenerationId,
      );
      ownerVetoes = [];
    } else if (arbitrator?.verdict === "veto") {
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerDecisions,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: false, reason: `Arbitrator vetoed ${targetId}: ${arbitrator.sourceId}` };
    } else {
      return await requireDecision(
        store,
        targetId,
        `Control owners have not authorized acceptance of ${targetId}`,
        [...evidence, ...ownerDecisions.flatMap(({ evidence: value }) => value)],
        arbitratorEdges.length > 0
          ? arbitratorEdges.map(({ from }) => from)
          : missingOwners.map(({ from }) => from),
        checkpointId,
        controlGenerationId,
      );
    }
  }

  if (ownerApprovals.length > 0 && ownerVetoes.length > 0) {
    if (!arbitrator)
      return await requireDecision(
        store,
        targetId,
        `Control owners disagree about ${targetId}`,
        [...evidence, ...ownerDecisions.flatMap(({ evidence: value }) => value)],
        arbitratorEdges.length > 0
          ? arbitratorEdges.map(({ from }) => from)
          : owners.map(({ from }) => from),
        checkpointId,
        controlGenerationId,
      );
    if (arbitrator.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        [],
        checkpointId,
        controlGenerationId,
      );
      ownerVetoes = [];
    } else {
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerDecisions,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: false, reason: `Arbitrator vetoed ${targetId}: ${arbitrator.sourceId}` };
    }
  }
  if (ownerVetoes.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        ownerVetoes,
        [],
        checkpointId,
        controlGenerationId,
      );
      ownerVetoes = [];
      ownerApprovals = [];
    } else if (arbitrator?.verdict === "veto") {
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerVetoes,
        arbitrator.evidence,
        checkpointId,
        controlGenerationId,
      );
      return { allowed: false, reason: `Arbitrator vetoed ${targetId}: ${arbitrator.sourceId}` };
    }
  }
  if (ownerVetoes.length > 0) {
    const reason = `Control owner vetoed ${targetId}: ${ownerVetoes.map(({ sourceId }) => sourceId).join(", ")}`;
    await recordResolution(
      store,
      targetId,
      "vetoed",
      ownerVetoes,
      evidence,
      checkpointId,
      controlGenerationId,
    );
    return { allowed: false, reason };
  }

  const vetoes = incoming
    .filter(({ relation }) => relation === "vetoes")
    .map((edge) =>
      decisionFor(state, edge.from, targetId, store.governanceControlIdentityHashAlgorithm),
    )
    .filter((decision): decision is ControlDecision => decision?.verdict === "veto");
  if (vetoes.length > 0) {
    if (arbitrator?.verdict === "approve") {
      await recordOverride(
        store,
        targetId,
        arbitrator,
        vetoes,
        [],
        checkpointId,
        controlGenerationId,
      );
    } else if (arbitrator?.verdict === "veto") {
      const reason = `Arbitrator vetoed ${targetId}: ${arbitrator.sourceId}`;
      await recordResolution(
        store,
        targetId,
        "vetoed",
        ownerApprovals,
        [...evidence, ...arbitrator.evidence],
        checkpointId,
        controlGenerationId,
      );
      return { allowed: false, reason };
    } else if (ownerApprovals.length > 0) {
      return await requireDecision(
        store,
        targetId,
        `Owner approval conflicts with a veto on ${targetId}`,
        [...evidence, ...vetoes.flatMap(({ evidence: value }) => value)],
        arbitratorEdges.length > 0
          ? arbitratorEdges.map(({ from }) => from)
          : owners.map(({ from }) => from),
        checkpointId,
        controlGenerationId,
      );
    } else {
      const reason = `Control vetoed ${targetId}: ${vetoes
        .map(({ sourceId, rationale }) => `${sourceId} (${rationale})`)
        .join(", ")}`;
      await recordResolution(
        store,
        targetId,
        "vetoed",
        [],
        [...evidence, ...vetoes.flatMap(({ evidence: value }) => value)],
        checkpointId,
        controlGenerationId,
      );
      return { allowed: false, reason };
    }
  }

  await recordResolution(
    store,
    targetId,
    "approved",
    ownerApprovals,
    evidence,
    checkpointId,
    controlGenerationId,
  );
  return { allowed: true };
}

export async function decideRunControl(
  store: RunStore,
  input: UserControlDecisionInput,
): Promise<RunState> {
  await store.prepareStorage();
  const lock = new RunLock(join(store.graphcraftRoot, "locks", `${store.runId}.lock`));
  await lock.acquire();
  try {
    const [graph, state] = await Promise.all([store.loadGraph(), store.loadState()]);
    const anchor = graph.anchors.find(({ id }) => id === input.sourceId);
    if (!anchor || anchor.owner !== "user")
      throw new Error(`Control source ${input.sourceId} is not owned by the user`);
    if (!authorityEdge(graph, input.sourceId, input.targetId))
      throw new Error(`Control source ${input.sourceId} has no authority over ${input.targetId}`);
    if (
      state.pendingDecision?.targetId === input.targetId &&
      !state.pendingDecision.requiredSources.includes(input.sourceId)
    ) {
      throw new Error(
        `Decision for ${input.targetId} requires one of: ${state.pendingDecision.requiredSources.join(", ")}`,
      );
    }
    const previous = state.controlDecisions.findLast(
      ({ sourceId, targetId }) => sourceId === input.sourceId && targetId === input.targetId,
    );
    if (previous?.sticky && input.replaces !== previous.decisionId)
      throw new Error(`Sticky decision ${previous.decisionId} requires explicit replacement`);
    if (input.replaces && previous?.decisionId !== input.replaces)
      throw new Error(`Replacement decision ${input.replaces} is not current`);
    const decision = ControlDecisionSchema.parse({
      schemaVersion: 1,
      decisionId: randomUUID(),
      sourceId: input.sourceId,
      targetId: input.targetId,
      verdict: input.verdict,
      rationale: input.rationale,
      evidence: input.evidence ?? [],
      actor: "user",
      sticky: true,
      decidedAt: new Date().toISOString(),
      ...(input.replaces ? { replaces: input.replaces } : {}),
    });
    await appendDecision(store, decision);
    return await store.loadState();
  } finally {
    await lock.release();
  }
}
